using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Threading.Tasks;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {partial class MainForm {
readonly List<D> assistantHistory=new List<D>();string assistantDraft="";bool assistantPending;Func<string,D,D> assistantTransport;
static IEnumerable<Control> FindControls(Control c){foreach(Control x in c.Controls){yield return x;foreach(Control y in FindControls(x))yield return y;}}
D AssistantCall(string m,D a){return assistantTransport==null?b.Call(m,a):assistantTransport(m,a);}
string AssistantTranscript(){return String.Join("\r\n\r\n",assistantHistory.Select(h=>(J.Text(h,"role")=="user"?"[내 질문]\r\n":"[AI 답변]\r\n")+J.Text(h,"text")));}
internal void AssistantWorkspace(){
var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6};foreach(int h in new[]{74,126,45,58,48})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(layout);
layout.Controls.Add(new Label{Dock=DockStyle.Fill,ForeColor=Style.Muted,Text="검토 대상을 고르지 않고 바로 질문하세요. 최근 최대 4회 문답을 참고합니다.\n현재 연결: "+(b.IsRemote?b.RemoteUrl:"이 PC 로컬 서버 · 클라우드 계정/키와 별도")+"\n대화는 메모리에만 보관합니다. 실시간 웹검색은 제공하지 않습니다."},0,0);
var question=new TextBox{Name="assistantQuestion",Dock=DockStyle.Fill,Multiline=true,MaxLength=6000,ScrollBars=ScrollBars.Vertical,Text=assistantDraft,Font=new Font(Premium.Family,12)};question.TextChanged+=(s,e)=>assistantDraft=question.Text;layout.Controls.Add(question,0,1);
var depth=new ComboBox{Name="assistantDepth",Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};depth.Items.AddRange(new object[]{"실무 상세 (기본) · 근거, 계산식, 예시, 작업 순서","핵심 요약"});depth.SelectedIndex=0;layout.Controls.Add(depth,0,2);
var consent=new CheckBox{Name="assistantConsent",Dock=DockStyle.Fill,Text="질문과 최근 대화를 Gemini에 전송하는 데 동의합니다. 개인정보·기밀을 적지 마세요.\n무료 API 입력은 제공업체의 서비스 개선에 사용될 수 있습니다. 등록 현장 자료는 자동 전송하지 않습니다."};layout.Controls.Add(consent,0,3);
var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(bar,0,4);var output=new TextBox{Name="assistantOutput",Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,Font=new Font(Premium.Family,12),Text=assistantHistory.Count==0?"궁금한 내용과 치수·수량·전압·예산 등 현재 조건을 적어 질문하세요.\r\n예: 24V LED 8m, 1m당 10W일 때 전원장치 선정 예시를 계산해 줘.":AssistantTranscript()};layout.Controls.Add(output,0,5);
var ask=Style.Button("AI에게 질문",async(s,e)=>{if(assistantPending)return;string q=question.Text.Trim();if(q.Length==0){output.Text="질문을 입력하세요.";return;}if(!consent.Checked){output.Text="질문과 최근 대화의 외부 전송에 동의해 주세요.";return;}var args=J.Row("kind","chat","question",q,"detail",depth.SelectedIndex==0?"detailed":"brief","consent",true,"history",assistantHistory.Select(J.Clone).ToArray());assistantPending=true;bar.Enabled=false;question.Enabled=false;output.Text="AI 답변을 받고 있습니다…";try{D result=await Task.Run(()=>AssistantCall("assistantAsk",args));assistantHistory.Add(J.Row("role","user","text",q));assistantHistory.Add(J.Row("role","model","text",J.Text(result,"answer")));while(assistantHistory.Count>8||J.S.Serialize(assistantHistory).Length>85000)assistantHistory.RemoveRange(0,2);assistantDraft="";if(!output.IsDisposed){question.Clear();output.Text=AssistantTranscript()+"\r\n\r\n모델: "+J.Text(result,"model")+"\r\n"+J.Text(result,"notice")+(J.Bool(result,"truncated")?"\r\n답변 한도에 도달했습니다. 이어서 설명해 달라고 질문하세요.":"");output.SelectionStart=output.TextLength;output.ScrollToCaret();}}catch(Exception ex){if(!output.IsDisposed)output.Text=AssistantTranscript()+"\r\n\r\n[요청 실패]\r\n"+ex.Message;}finally{assistantPending=false;if(!bar.IsDisposed){bar.Enabled=true;question.Enabled=true;}}});ask.Name="assistantAsk";bar.Controls.Add(ask);
bar.Controls.Add(Style.Button("새 대화",(s,e)=>{if(assistantPending)return;if(MessageBox.Show("현재 대화를 지우고 새로 시작할까요?","새 대화",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;assistantHistory.Clear();assistantDraft="";question.Clear();consent.Checked=false;output.Text="새 질문을 입력하세요.";}));
bar.Controls.Add(Style.Button("연결 설정 확인",async(s,e)=>{bar.Enabled=false;try{D r=await Task.Run(()=>AssistantCall("assistantStatus",new D()));if(!output.IsDisposed)output.Text=(J.Bool(r,"configured")?"API 키 등록됨 · AI 질문으로 실제 연결을 확인하세요.":"현재 연결된 서버에 API 키가 없습니다.")+"\r\n"+J.Text(r,"notice");}catch(Exception ex){if(!output.IsDisposed)output.Text=ex.Message;}finally{if(!bar.IsDisposed)bar.Enabled=true;}}));
if(J.Text(user,"role")=="admin")bar.Controls.Add(Style.Button("관리자 API 키 설정",(s,e)=>AssistantKeySettings()));
if(assistantPending){bar.Enabled=false;output.Text="기존 요청의 답변을 기다리는 중입니다. 응답 후 화면을 다시 열면 대화를 확인할 수 있습니다.";}
}
void AssistantKeySettings(){if(b.IsRemote&&!b.RemoteUrl.StartsWith("https://",StringComparison.OrdinalIgnoreCase)){MessageBox.Show("키 전송에는 HTTPS 클라우드 연결이 필요합니다.");return;}var f=new Form{Text="관리자 · AI API 키 설정",Width=650,Height=450};Style.Form(f);var p=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),FlowDirection=FlowDirection.TopDown,WrapContents=false};f.Controls.Add(p);p.Controls.Add(new Label{Width=570,Height=78,Text="현재 연결된 서버에 Gemini API 키를 저장합니다. 휴대폰과 같은 클라우드에 연결하면 기존 키를 함께 사용합니다.\n키를 로그인 설정에 저장하지 않습니다. API 키와 로그인 비밀번호는 별개입니다."});var key=new TextBox{Width=560,UseSystemPasswordChar=true,MaxLength=4096};p.Controls.Add(key);var free=new CheckBox{Width=560,Height=66,Text="결제 연결 없는 무료 프로젝트임을 확인했습니다. 무료 API 입력의 서비스 개선 사용 정책을 확인했습니다."};p.Controls.Add(free);var message=new Label{Width=560,Height=65};p.Controls.Add(message);p.Controls.Add(Style.Button("서버에 저장",async(s,e)=>{if(!free.Checked){message.Text="무료 프로젝트 여부를 확인하세요.";return;}string value=key.Text;if(String.IsNullOrWhiteSpace(value)){message.Text="API 키를 입력하세요.";return;}key.Clear();f.Enabled=false;try{D r=await Task.Run(()=>b.Call("assistantConfigure",J.Row("key",value,"freeProject",true)));if(!message.IsDisposed)message.Text=J.Text(r,"notice");}catch(Exception ex){if(!message.IsDisposed)message.Text=ex.Message;}finally{value="";if(!f.IsDisposed)f.Enabled=true;}}));f.FormClosing+=(s,e)=>key.Clear();OpenWorkspace(f);}
internal void ValidateAssistant(string dir){if(!dir.Contains("qa-native"))throw new Exception("Isolated QA storage required");int calls=0;assistantHistory.Clear();assistantTransport=(method,args)=>{if(method!="assistantAsk"||J.Text(args,"kind")!="chat"||args.ContainsKey("id")||args.ContainsKey("previewToken")||J.Rows(args,"history").Count!=calls*2||J.Text(args,"detail")!="detailed")throw new Exception("Native free chat request invalid");calls++;return J.Row("answer","QA native answer "+calls,"model","mock-only","notice","가상 응답 · 실제 공급자 응답 아님");};try{ShowPage("assistant");Application.DoEvents();for(int turn=0;turn<2;turn++){var all=FindControls(content).ToList();all.OfType<TextBox>().First(x=>x.Name=="assistantQuestion").Text=turn==0?"QA first question":"QA follow-up";all.OfType<CheckBox>().First().Checked=true;all.OfType<Button>().First(x=>x.Name=="assistantAsk").PerformClick();var end=DateTime.UtcNow.AddSeconds(8);while(assistantPending&&DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}if(assistantPending||!all.OfType<TextBox>().First(x=>x.ReadOnly).Text.Contains("QA native answer "+(turn+1)))throw new Exception("Native answer not rendered");}using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(System.IO.Path.Combine(dir,"native-assistant.png"));}System.IO.File.WriteAllText(System.IO.Path.Combine(dir,"assistant-test.json"),"{\"nativeFreeChat\":true,\"followupHistory\":true,\"detailedDefault\":true,\"liveProvider\":false}");}finally{assistantTransport=null;assistantHistory.Clear();assistantDraft="";}}
}}
